  assign p19 = p1 ? 1'bz : q[0];
  assign p18 = p1 ? 1'bz : q[1];
  assign p17 = p1 ? 1'bz : q[2];
  assign p16 = p1 ? 1'bz : q[3];
  assign p15 = p1 ? 1'bz : q[4];
  assign p14 = p1 ? 1'bz : q[5];
  assign p13 = p1 ? 1'bz : q[6];
  assign p12 = p1 ? 1'bz : q[7];
endmodule

// 74xx:74LS148: 1=I4, 2=I5, 3=I6, 4=I7, 5=EI, 6=S2, 7=S1, 9=S0, 10=IO, 11=I1, 12=I2, 13=I3, 14=GS, 15=EO
module m_74xx_74LS148 (p1, p2, p3, p4, p5, p6, p7, p9, p10, p11, p12, p13, p14, p15);
  input p1;
  input p2;
  input p3;
  input p4;
  input p5;
  output p6;
  output p7;
  output p9;
  input p10;
  input p11;
  input p12;
  input p13;
  output p14;
  output p15;

  // 8-to-3 priority encoder, active-low inputs/outputs
  // I0..I7 = 10,11,12,13,1,2,3,4   EI=5
  // S0=9 S1=7 S2=6   GS=14 EO=15
  reg [2:0] code;
  reg gs, eo;
  always @* begin
    if (p5)            begin code = 3'b111; gs = 1'b1; eo = 1'b1; end
    else if (!p4)      begin code = ~3'd7;  gs = 1'b0; eo = 1'b1; end
    else if (!p3)      begin code = ~3'd6;  gs = 1'b0; eo = 1'b1; end
    else if (!p2)      begin code = ~3'd5;  gs = 1'b0; eo = 1'b1; end
    else if (!p1)      begin code = ~3'd4;  gs = 1'b0; eo = 1'b1; end
    else if (!p13)     begin code = ~3'd3;  gs = 1'b0; eo = 1'b1; end
    else if (!p12)     begin code = ~3'd2;  gs = 1'b0; eo = 1'b1; end
    else if (!p11)     begin code = ~3'd1;  gs = 1'b0; eo = 1'b1; end
    else if (!p10)     begin code = ~3'd0;  gs = 1'b0; eo = 1'b1; end
    else               begin code = 3'b111; gs = 1'b1; eo = 1'b0; end
  end
  assign p9  = code[0];
  assign p7  = code[1];
  assign p6  = code[2];
  assign p14 = gs;
  assign p15 = eo;
endmodule

// Memory_EPROM:27C512: 1=A15, 2=A12, 3=A7, 4=A6, 5=A5, 6=A4, 7=A3, 8=A2, 9=A1, 10=A0, 11=D0, 12=D1, 13=D2, 15=D3, 16=D4, 17=D5, 18=D6, 19=D7, 20=~{CE}, 21=A10, 22=~{OE}, 23=A11, 24=A9, 25=A8, 26=A13, 27=A14
module m_Memory_EPROM_27C512 (p1, p2, p3, p4, p5, p6, p7, p8, p9, p10, p11, p12, p13, p15, p16, p17, p18, p19, p20, p21, p22, p23, p24, p25, p26, p27);
  input p1;
  input p2;
  input p3;
  input p4;
  input p5;
  input p6;
  input p7;
  input p8;
  input p9;
  input p10;
  inout p11;
  inout p12;
  inout p13;
  inout p15;
  inout p16;
  inout p17;
  inout p18;
  inout p19;
  input p20;
  input p21;
  input p22;
  input p23;
  input p24;
  input p25;
  input p26;
  input p27;

  // 64K x 8 OTP EPROM.  A0..A15 = 10,9,8,7,6,5,4,3,25,24,21,23,2,26,27,1
  // D0..D7 = 11,12,13,15,16,17,18,19   ~CE=20 ~OE=22
  parameter INIT = "";
  reg [7:0] mem [0:65535];
  integer i;
  initial begin
    for (i = 0; i < 65536; i = i + 1) mem[i] = 8'h00;
    if (INIT != "") $readmemh(INIT, mem);
  end
  wire [15:0] a_raw = {p1, p27, p26, p2, p23, p21, p24, p25,
                       p3, p4, p5, p6, p7, p8, p9, p10};
  // X-optimistic decode: an unknown address bit reads as 0.  Real hardware
  // always has a definite level here; this only avoids 4-state X-lock while
  // the power-up state of the DONE/REQ registers is still unknown.
  reg [15:0] a;
  integer j;
  always @* for (j = 0; j < 16; j = j + 1) a[j] = (a_raw[j] === 1'b1);
  wire oe = ~p20 & ~p22;
  wire [7:0] dout = mem[a];
  assign p11 = oe ? dout[0] : 1'bz;
  assign p12 = oe ? dout[1] : 1'bz;
  assign p13 = oe ? dout[2] : 1'bz;
  assign p15 = oe ? dout[3] : 1'bz;
  assign p16 = oe ? dout[4] : 1'bz;
  assign p17 = oe ? dout[5] : 1'bz;
  assign p18 = oe ? dout[6] : 1'bz;
  assign p19 = oe ? dout[7] : 1'bz;
endmodule

// Memory_RAM:CY62256-70PC: 1=A14, 2=A12, 3=A7, 4=A6, 5=A5, 6=A4, 7=A3, 8=A2, 9=A1, 10=A0, 11=Q0, 12=Q1, 13=Q2, 15=Q3, 16=Q4, 17=Q5, 18=Q6, 19=Q7, 20=~{CS}, 21=A10, 22=~{OE}, 23=A11, 24=A9, 25=A8, 26=A13, 27=~{WE}
module m_Memory_RAM_CY62256_70PC (p1, p2, p3, p4, p5, p6, p7, p8, p9, p10, p11, p12, p13, p15, p16, p17, p18, p19, p20, p21, p22, p23, p24, p25, p26, p27);
  input p1;
  input p2;
  input p3;
  input p4;
  input p5;
  input p6;
  input p7;
  input p8;
  input p9;
  input p10;
  inout p11;
  inout p12;
  inout p13;
  inout p15;
  inout p16;
  inout p17;
  inout p18;
  inout p19;
  input p20;
  input p21;
  input p22;
  input p23;
  input p24;
  input p25;
  input p26;
  input p27;

  // 32K x 8 SRAM (MEM_BOOT swap for 28C256; pin-compatible DIP-28,
  // wired 1=A14 26=A13 20=~CE 22=~OE 27=~WE).
  parameter INIT = "";
  reg [7:0] mem [0:32767];
  integer i;
  initial begin
    for (i = 0; i < 32768; i = i + 1) mem[i] = 8'h00;
    if (INIT != "") $readmemh(INIT, mem);
  end
  wire [14:0] a_raw = {p1, p26, p2, p23, p21, p24, p25,
                       p3, p4, p5, p6, p7, p8, p9, p10};
  reg [14:0] a;
  integer j;
  always @* for (j = 0; j < 15; j = j + 1) a[j] = (a_raw[j] === 1'b1);
  wire [7:0] din = {p19, p18, p17, p16, p15, p13, p12, p11};
  wire oe = ~p20 & ~p22 & p27;
  wire [7:0] dout = mem[a];
  assign p11 = oe ? dout[0] : 1'bz;
  assign p12 = oe ? dout[1] : 1'bz;
  assign p13 = oe ? dout[2] : 1'bz;
  assign p15 = oe ? dout[3] : 1'bz;
  assign p16 = oe ? dout[4] : 1'bz;
  assign p17 = oe ? dout[5] : 1'bz;
  assign p18 = oe ? dout[6] : 1'bz;
  assign p19 = oe ? dout[7] : 1'bz;
  always @(posedge p27)
    if (!p20) mem[a] <= din;
endmodule

// Memory_RAM:HY6264AxP: 2=A12, 3=A7, 4=A6, 5=A5, 6=A4, 7=A3, 8=A2, 9=A1, 10=A0, 11=I/O0, 12=I/O1, 13=I/O2, 15=I/O3, 16=I/O4, 17=I/O5, 18=I/O6, 19=I/O7, 20=~{CS1}, 21=A10, 22=~{OE}, 23=A11, 24=A9, 25=A8, 26=CS2, 27=~{WE}
module m_Memory_RAM_HY6264AxP (p2, p3, p4, p5, p6, p7, p8, p9, p10, p11, p12, p13, p15, p16, p17, p18, p19, p20, p21, p22, p23, p24, p25, p26, p27);
  input p2;
  input p3;
  input p4;
  input p5;
  input p6;
  input p7;
  input p8;
  input p9;
  input p10;
  inout p11;
  inout p12;
  inout p13;
  inout p15;
  inout p16;
  inout p17;
  inout p18;
  inout p19;
  input p20;
  input p21;
  input p22;
  input p23;
  input p24;
  input p25;
  input p26;
  input p27;

  // 8K x 8 SRAM.  A0..A12 = 10,9,8,7,6,5,4,3,25,24,21,23,2
  // I/O0..7 = 11,12,13,15,16,17,18,19   ~CS1=20 CS2=26 ~OE=22 ~WE=27
  parameter INIT = "";
  reg [7:0] mem [0:8191];
  integer i;
  initial begin
    for (i = 0; i < 8192; i = i + 1) mem[i] = 8'h00;
    if (INIT != "") $readmemh(INIT, mem);
  end
  wire [12:0] a_raw = {p2, p23, p21, p24, p25,
                       p3, p4, p5, p6, p7, p8, p9, p10};
  reg [12:0] a;
  integer j;
  always @* for (j = 0; j < 13; j = j + 1) a[j] = (a_raw[j] === 1'b1);
  wire [7:0] din = {p19, p18, p17, p16, p15, p13, p12, p11};
  wire sel = ~p20 & p26;
  wire oe = sel & ~p22 & p27;
  wire [7:0] dout = mem[a];
  assign p11 = oe ? dout[0] : 1'bz;
  assign p12 = oe ? dout[1] : 1'bz;
  assign p13 = oe ? dout[2] : 1'bz;
  assign p15 = oe ? dout[3] : 1'bz;
  assign p16 = oe ? dout[4] : 1'bz;
  assign p17 = oe ? dout[5] : 1'bz;
  assign p18 = oe ? dout[6] : 1'bz;
  assign p19 = oe ? dout[7] : 1'bz;
  always @(posedge p27)
    if (sel) mem[a] <= din;
endmodule

// Oscillator:ASE-xxxMHz: 1=EN, 3=OUT
module m_Oscillator_ASE_xxxMHz (p1, p3);
  input p1;
  output p3;

  // 4-pin active oscillator: EN=1 OUT=3 (GND/Vdd are power pins)
  parameter HALF_NS = 500.0;   // 1m Hz   // 8.000 MHz
  reg clk = 1'b0;
  always #(HALF_NS) clk = ~clk;
  assign p3 = clk;
endmodule

// ---- EDA-only models (gen_eda_dut support) ----

// 8-pin DIP oscillator can (ACH-8.000MHZ-EK): EN=1, CASE/GND=4, OUT=5, Vdd=8
module m_Osc_ACH (p1, p5);
  input p1;
  output p5;
  parameter HALF_NS = 500.0;   // 1m Hz   // 8.000 MHz
  reg clk = 1'b0;
  always #(HALF_NS) clk = ~clk;
  assign p5 = clk;
endmodule

