// 74HC86 quad 2-input XOR: (1,2)->3 (4,5)->6 (9,10)->8 (12,13)->11
module m_74xx_74HC86 (p1, p2, p3, p4, p5, p6, p8, p9, p10, p11, p12, p13);
  input p1, p2, p4, p5, p9, p10, p12, p13;
  output p3, p6, p8, p11;
  assign p3  = p1  ^ p2;
  assign p6  = p4  ^ p5;
  assign p8  = p9  ^ p10;
  assign p11 = p12 ^ p13;
endmodule
